  internal void SetDocument(RobotDocument document){EndPoseEdit();Document=document;selectedJoint=document.Joints.Select(j=>j.Id).FirstOrDefault();selectedPart=null;fitNext=true;Rebuild();if(document.Joints.Any(j=>j.BodyStyle==RobotBodyStyle.Закрытый_трубчатый))view.SelectedIndex=1;if(document.Joints.Count>0&&document.Joints.All(j=>j.GeneratedBody!=null&&j.GeneratedBody.Result.GeometryValid))SetStage(2);}
  void Rebuild(RobotBuild prepared=null){if(fitNext)webFit=true;EndPoseEdit();Stop();revision++;restoreCamera=!fitNext&&Scene.Ready;if(restoreCamera){cameraTarget=Scene.Camera.Target;cameraWidth=Scene.Camera.Width;cameraYaw=Scene.Camera.Yaw;cameraPitch=Scene.Camera.Pitch;}Build=prepared??RobotCad.Build(Document);Analysis=RobotSolver.Solve(Build);updating=true;try{tree.BeginUpdate();tree.Nodes.Clear();var nodes=new Dictionary<string,TreeNode>();foreach(var j in Document.Ordered()){var n=new TreeNode(j.Name){Tag="j|"+j.Id};nodes[j.Id]=n;if(j.ParentId==null||!nodes.ContainsKey(j.ParentId))tree.Nodes.Add(n);else nodes[j.ParentId].Nodes.Add(n);var parts=new TreeNode("Детали");foreach(var e in Build.Entries.Values.Where(e=>e.JointId==j.Id&&!e.Guide))parts.Nodes.Add(new TreeNode(e.Part.Label){Tag="p|"+e.Id});n.Nodes.Add(parts);n.Expand();}tree.EndUpdate();}finally{updating=false;}phase=0;Scene.Phase=0;Scene.SetResult(new Result{P=new Parameters{Kind=9},Model=Build.Model,Robot=Build},true);fitNext=false;UpdateAnalysis();if(Joint==null)selectedJoint=Document.Joints.Select(j=>j.Id).FirstOrDefault();if(Entry==null)selectedPart=null;Select(selectedJoint,selectedPart);last=Document.Serialize();QueueBodyRegeneration();RenderWebRobot();Text="GearLab 5.6 · "+(path==null?Document.Name:Path.GetFileName(path))+(last!=saved?" *":"");}
  void Filter(){if(Build==null||!Scene.Ready)return;Scene.Hidden.Clear();foreach(var e in Build.Entries.Values){bool show=view.SelectedIndex==0?(e.Guide||e.Category=="Мотор"):view.SelectedIndex==2?e.Printable&&!e.Guide:!e.Guide;if(!show)Scene.Hidden.Add(e.Id);}Scene.RefreshVisibility();FilterWebRobot();}
  void Select(string joint,string part){if(joint!=selectedJoint)EndPoseEdit();selectedJoint=Document.Find(joint)==null?null:joint;selectedPart=part;updating=true;try{parent.Items.Clear();parent.Items.Add(new ParentItem{Id=null,Text="Основание / мировые координаты"});if(Joint!=null){foreach(var candidate in Document.Joints.Where(j=>j.Id!=Joint.Id&&!Document.Descendant(j.Id,Joint.Id)))parent.Items.Add(new ParentItem{Id=candidate.Id,Text=candidate.Name});foreach(ParentItem item in parent.Items)if(item.Id==Joint.ParentId){parent.SelectedItem=item;break;}var pose=Build.Current!=null&&Build.Current.ContainsKey(Joint.Id)?Build.Current[Joint.Id]:null;detail.Text=Joint.Name+(Entry==null?"":" · "+Entry.Part.Label)+(pose==null?"":"\nНачало: "+Engine.F(pose.Origin.X)+"; "+Engine.F(pose.Origin.Y)+"; "+Engine.F(pose.Origin.Z)+" мм");}else detail.Text="Добавьте кость / шарнир.";scope.Enabled=Entry!=null&&Entry.Shape!=null&&Entry.Category=="Корпус";if(!scope.Enabled||view.SelectedIndex==0)scope.SelectedIndex=0;else if(view.SelectedIndex!=0)scope.SelectedIndex=1;FillProperties();foreach(TreeNode node in tree.Nodes){var match=FindNode(node,selectedPart==null?"j|"+selectedJoint:"p|"+selectedPart);if(match!=null){tree.SelectedNode=match;break;}}Scene.Select(selectedPart);robotWeb.Select(selectedPart??(selectedJoint==null?null:selectedJoint+"_end_guide"));UpdateWebPose();}finally{updating=false;}}
  static TreeNode FindNode(TreeNode node,string tag){if((string)node.Tag==tag)return node;foreach(TreeNode child in node.Nodes){var match=FindNode(child,tag);if(match!=null)return match;}return null;}
  void FillProperties(){RefreshQuickInspector();RefreshBoneOverlay();editShape=null;if(Entry!=null&&Entry.Part.NativeStep!=null&&scope.SelectedIndex==1){properties.SelectedObject=new CADNativeInfo();return;}if(scope.SelectedIndex==1&&Entry!=null&&Entry.Shape!=null&&Entry.Category=="Корпус"){editShape=Entry.Shape.CloneShape();properties.SelectedObject=new MechanismProperties(editShape);}else properties.SelectedObject=Joint;}
  void UpdateAnalysis(){RefreshQuickLoad();loads.Rows.Clear();foreach(var s in Analysis.Joints){var j=Document.Find(s.Id);loads.Rows.Add(j.Name,Engine.F(s.Required)+" "+s.Unit,j.Mode==RobotJointMode.Неподвижный?"—":Engine.F(s.Available)+" "+s.Unit,Engine.F(s.MotorRequired),Engine.F(s.MotorRpm),s.Message);if(!s.Enough)loads.Rows[loads.Rows.Count-1].DefaultCellStyle.ForeColor=Color.Firebrick;}if(!Analysis.Valid){summary.ForeColor=Color.Firebrick;summary.Text=string.Join("; ",Analysis.Errors.Take(2));}else{int failed=Analysis.Joints.Count(j=>!j.Enough);summary.ForeColor=failed>0?Color.Firebrick:Color.FromArgb(38,118,85);summary.Text=Document.Joints.Count+" звеньев · масса модели и нагрузки "+Engine.F(Analysis.TotalMass)+" кг · запас ×"+Engine.F(Document.SafetyFactor)+" · "+(failed>0?failed+" приводов не проходят оценку":"Статическая оценка проходит")+(Analysis.SampledPoses>0?" · "+Analysis.SampledPoses+" выборочных поз":" · текущая поза");}int pending=Document.Joints.Count(j=>j.BodyGenerator!=null&&j.BodyGenerator.Enabled&&(j.GeneratedBody==null||j.GeneratedBody.Result.Mates==null));int unspecified=Document.Joints.Count(j=>j.Mode!=RobotJointMode.Неподвижный&&j.ReducerSettings==null&&j.CustomTransmission==null);if(pending>0){summary.Text+=" · стыки ещё не построены: "+pending;summary.ForeColor=Color.Firebrick;}else if(unspecified>0){summary.Text+=" · CAD-редуктор не выбран: "+unspecified;summary.ForeColor=Color.DarkGoldenrod;}notes.Text=string.Join("\r\n\r\n",Analysis.Errors.Concat(Analysis.Notes));play.Enabled=Build.Model.Valid&&Document.Joints.Count>0;}
  bool Mutate(Action action){var before=Document.Serialize();try{action();var errors=Document.Validate();if(errors.Count>0)throw new Exception(string.Join("\n",errors.Take(5)));var candidate=RobotCad.Build(Document);if(candidate.Model.Errors.Count>0)throw new Exception(string.Join("\n",candidate.Model.Errors.Take(5)));if(before!=Document.Serialize()){undo.Push(before);redo.Clear();}Rebuild(candidate);return true;}catch(Exception ex){Document=RobotDocument.Parse(before);Rebuild();MessageBox.Show(this,ex.Message,"Изменение не применено");return false;}}
  internal void ApplyEnclosedStyle(){ReconnectRobot();view.SelectedIndex=1;}
  void PropertyChanged(string name){if(updating)return;string before=last;try{if(scope.SelectedIndex==1&&editShape!=null){PutEdit(selectedPart,editShape,null);}else if(Joint!=null&&name=="MotorTemplate")Joint.ApplyMotorTemplate();var errors=Document.Validate();var model=RobotCad.Build(Document);if(errors.Count>0||model.Model.Errors.Count>0)throw new Exception(string.Join("\n",errors.Concat(model.Model.Errors).Take(5)));undo.Push(before);redo.Clear();Rebuild(model);}catch(Exception ex){Document=RobotDocument.Parse(before);Rebuild();MessageBox.Show(this,ex.Message,"Параметры не применены");}}
  void PutEdit(string id,MechanismPart shape,MeshDocument mesh){var e=Document.BodyEdits.FirstOrDefault(a=>a.PartId==id);if(e==null){e=new RobotBodyEdit{PartId=id};Document.BodyEdits.Add(e);}e.Shape=shape==null?e.Shape:shape.CloneShape();e.Mesh=mesh;e.NativeProject=null;e.NativeStep=null;e.NativePreview=null;e.NativeVolume=0;e.NativeCentre=null;e.NativeShift=null;}
  void ChangeParent(){if(updating||Joint==null||!(parent.SelectedItem is ParentItem))return;var joint=Joint;var item=(ParentItem)parent.SelectedItem;if(item.Id==joint.ParentId)return;Mutate(()=>{var world=Build.Current[joint.Id].Origin;var frame=item.Id==null?Matrix3D.Identity:Build.Current[item.Id].End;frame.Invert();var point=frame.Transform(world);joint.ParentId=item.Id;joint.OffsetX=point.X;joint.OffsetY=point.Y;joint.OffsetZ=point.Z;});}
  void AddJoint(){CapturePose();var previous=Joint;Mutate(()=>{var j=Document.Add(previous==null?null:previous.Id);if(previous==null)j.OffsetZ=95;else{j.OffsetX=j.Axis.X*100;j.OffsetY=j.Axis.Y*100;j.OffsetZ=j.Axis.Z*100;j.EndX=140;}j.Appearance=RobotAppearance.Чёрный_оранжевый;j.BodyStyle=RobotBodyStyle.Закрытый_трубчатый;j.BodyGenerator=new ProceduralBodySettings{Connected=true};selectedJoint=j.Id;selectedPart=null;});}
  void Delete(){if(Joint==null)return;string id=Joint.Id;Mutate(()=>{Document.Remove(id);selectedJoint=null;selectedPart=null;});}
  void CommitDrag(string id,Vector3D delta){RobotCadEntry e;if(!Build.Entries.TryGetValue(id,out e))return;var j=Document.Find(e.JointId);if(j==null)return;Stop();if(view.SelectedIndex==0||e.Guide){if(id.EndsWith("_end_guide",StringComparison.Ordinal)){var inverse=Build.Current[j.Id].Output;inverse.Invert();var d=inverse.Transform(delta);Mutate(()=>{j.EndX=AppSettings.Snap(j.EndX+d.X);j.EndY=AppSettings.Snap(j.EndY+d.Y);j.EndZ=AppSettings.Snap(j.EndZ+d.Z);});}else if(e.Category=="Мотор"){var transform=RobotMath.Frame(j.Axis)*Build.Current[j.Id].Base;transform.Invert();var d=transform.Transform(delta);if(Math.Abs(d.Z)>.1){Rebuild();notes.AppendText("\r\nМотор закреплён в монтажной плоскости: осевое расстояние задаётся длиной корпуса передачи.");return;}Mutate(()=>{j.MotorOffsetX=AppSettings.Snap(j.MotorOffsetX+d.X);j.MotorOffsetY=AppSettings.Snap(j.MotorOffsetY+d.Y);});}else{var parentFrame=j.ParentId==null?Matrix3D.Identity:Build.Current[j.ParentId].End;parentFrame.Invert();var d=parentFrame.Transform(delta);Mutate(()=>{j.OffsetX=AppSettings.Snap(j.OffsetX+d.X);j.OffsetY=AppSettings.Snap(j.OffsetY+d.Y);j.OffsetZ=AppSettings.Snap(j.OffsetZ+d.Z);});}}else if(e.Part.NativeStep!=null&&e.Category=="Корпус"){var inverse=e.Part.Placement;inverse.Invert();var d=inverse.Transform(delta);Mutate(()=>{var edit=Document.BodyEdits.FirstOrDefault(a=>a.PartId==id);if(edit==null){edit=new RobotBodyEdit{PartId=id,NativeStep=e.Part.NativeStep,NativePreview=CADMeshCodec.Encode(e.Part.MeshOverride),NativeVolume=e.Part.NativeVolume,NativeCentre=new[]{e.Part.NativeCentre.X,e.Part.NativeCentre.Y,e.Part.NativeCentre.Z}};Document.BodyEdits.Add(edit);}if(edit.NativeShift==null)edit.NativeShift=new double[3];edit.NativeShift[0]=AppSettings.Snap(edit.NativeShift[0]+d.X);edit.NativeShift[1]=AppSettings.Snap(edit.NativeShift[1]+d.Y);edit.NativeShift[2]=AppSettings.Snap(edit.NativeShift[2]+d.Z);});}else if(e.Shape!=null&&e.Category=="Корпус"){var inverse=e.Part.Placement;inverse.Invert();var d=inverse.Transform(delta);var shape=e.Shape.CloneShape();Mutate(()=>{shape.X=AppSettings.Snap(shape.X+d.X);shape.Y=AppSettings.Snap(shape.Y+d.Y);shape.Z=AppSettings.Snap(shape.Z+d.Z);PutEdit(id,shape,null);});}else{Rebuild();notes.AppendText("\r\nЭтот узел связан с приводом: меняйте параметры звена или откройте его механизм.");}}
  void Holes(){if(NativeEditOnly())return;var e=Entry;if(e==null||e.Shape==null||e.Category!="Корпус"){MessageBox.Show(this,"Выберите CAD-деталь корпуса в режиме «Корпус».");return;}var shape=e.Shape.CloneShape();var rows=new BindingSource{DataSource=new BindingList<MechanismHole>(shape.Holes)};using(var d=new MechanismTableDialog("Отверстия: "+shape.Name,rows))if(d.ShowDialog(this)==DialogResult.OK)Mutate(()=>PutEdit(e.Id,shape,null));}
  void Steps(){if(NativeEditOnly())return;var e=Entry;if(e==null||e.Shape==null||e.Shape.Kind!="shaft"||e.Category!="Корпус"){MessageBox.Show(this,"Выберите круглую CAD-деталь корпуса.");return;}var shape=e.Shape.CloneShape();if(shape.Steps.Count==0)shape.Steps.Add(new MechanismStep{Diameter=shape.Diameter,Length=shape.Length,Bore=shape.Bore});var rows=new BindingSource{DataSource=new BindingList<MechanismStep>(shape.Steps)};using(var d=new MechanismTableDialog("Осевые сечения: "+shape.Name,rows))if(d.ShowDialog(this)==DialogResult.OK)Mutate(()=>{shape.Length=shape.Steps.Sum(s=>s.Length);PutEdit(e.Id,shape,null);});}
  void Sketch(){if(NativeEditOnly())return;var e=Entry;if(e==null||e.Shape==null||e.Shape.Kind!="sketch"){MessageBox.Show(this,"Выберите балку / выдавленный эскиз корпуса.");return;}var shape=e.Shape.CloneShape();using(var d=new MechanismSketchDialog(shape.Outline))if(d.ShowDialog(this)==DialogResult.OK)Mutate(()=>{shape.Outline=d.Points;PutEdit(e.Id,shape,null);});}
  void Polygon(){var e=Entry;if(e==null||e.Guide){WorkspaceHost.Navigate(this,"polygon");return;}var mesh=MeshDocument.FromScene(PrintExport.Mesh(e.Part),e.Part.Label);Func<MeshDocument,bool> apply=e.Shape!=null&&e.Category=="Корпус"?(Func<MeshDocument,bool>)(edited=>Mutate(()=>PutEdit(e.Id,e.Shape,edited))):null;WorkspaceHost.Open(this,new PolygonForm(mesh,apply));}
  void RestorePart(){if(Entry!=null){string id=Entry.Id;Mutate(()=>Document.BodyEdits.RemoveAll(e=>e.PartId==id));}}
  void Reducer(){var joint=Joint;if(joint==null)return;string jointId=joint.Id;var seed=joint.ReducerSettings==null?Engine.Starter(0):Engine.Clone(joint.ReducerSettings);if(joint.ReducerSettings==null){Engine.SetPreset(seed,2);seed.Ratio=Math.Max(3,Math.Min(120,Math.Round(joint.Reduction)));seed.RingOutput=true;seed.Overall=Math.Max(80,joint.GearboxDiameter);Engine.FitOverall(seed);}var form=new MainForm();form.ConfigureForRobot(seed,p=>Mutate(()=>{joint=Document.Find(jointId);if(joint==null)throw new Exception("Звено удалено. Откройте редактор для существующего звена.");var r=Engine.Calculate(p);r.Model=CadBuilder.Build(r);joint.ReducerSettings=p;joint.CustomTransmission=null;joint.TransmissionOutput=null;joint.Reduction=r.Actual;var bounds=r.Model.Bounds();joint.GearboxDiameter=Math.Max(joint.GearboxDiameter,Math.Min(250,2*Math.Max(Math.Max(Math.Abs(bounds[0]),Math.Abs(bounds[1])),Math.Max(Math.Abs(bounds[2]),Math.Abs(bounds[3])))+2*joint.Wall));}));form.ShowWorkspace(this);}
  void Transmission(){var joint=Joint;if(joint==null)return;string jointId=joint.Id;var seed=joint.CustomTransmission??joint.CreateTransmissionTemplate();var form=new MechanismForm();form.ConfigureForRobot(seed,(project,output)=>Mutate(()=>{joint=Document.Find(jointId);if(joint==null)throw new Exception("Звено удалено. Откройте редактор для существующего звена.");var solution=MechanismSolver.Solve(project);var shaft=project.Find(output);var motor=project.Find(project.DriveShaftId);joint.CustomTransmission=project;joint.TransmissionOutput=output;joint.ReducerSettings=null;joint.Reduction=1/Math.Abs(solution.Shafts[output].SpeedRatio);joint.Efficiency=solution.Shafts[output].PathEfficiency;joint.MotorOffsetX=motor.X-shaft.X;joint.MotorOffsetY=motor.Y-shaft.Y;motor.Bore=Math.Max(motor.Bore,joint.MotorShaft+2*joint.Fit);double top=shaft.Z+project.ShaftLength(shaft);joint.GearboxLength=Math.Max(15,Math.Min(180,top-motor.Z-joint.Wall));var bounds=MechanismCad.Build(project).Bounds();double radial=new[]{Math.Abs(bounds[0]-shaft.X),Math.Abs(bounds[1]-shaft.X),Math.Abs(bounds[2]-shaft.Y),Math.Abs(bounds[3]-shaft.Y),Math.Sqrt(Math.Pow(Math.Abs(joint.MotorOffsetX)+joint.MotorFrame/2,2)+Math.Pow(Math.Abs(joint.MotorOffsetY)+joint.MotorFrame/2,2))}.Max();joint.GearboxDiameter=Math.Max(joint.GearboxDiameter,2*(radial+joint.Wall+joint.Fit));}));form.ShowWorkspace(this);}
  void CheckRange(){if(!Build.Model.Valid)return;var snapshot=Document.Clone();int ticket=revision;range.Enabled=false;summary.Text="Проверка 48 поз и статических нагрузок…";Task.Factory.StartNew(()=>RobotSolver.CheckRange(RobotCad.Build(snapshot),48)).ContinueWith(task=>{if(IsDisposed)return;BeginInvoke(new Action(()=>{range.Enabled=true;if(task.IsFaulted){MessageBox.Show(this,task.Exception.GetBaseException().Message);return;}if(ticket!=revision){notes.AppendText("\r\nПосле запуска проверки проект изменился. Повторите проверку диапазона.");return;}Analysis=task.Result;UpdateAnalysis();}));});}
  internal void RefreshAnimatedLoads(double time){Analysis=RobotSolver.Solve(Build,RobotKinematics.Evaluate(Document,time,true));UpdateAnalysis();}
  void TogglePlay(){EndPoseEdit();if(playing){Stop();return;}if(!Scene.Ready||!Build.Model.Valid)return;updating=true;move.Checked=false;updating=false;Scene.SetMoveMode(false);playing=true;lastTick=clock.Elapsed.TotalSeconds;timer.Start();play.Text="Ⅱ Пауза";}
  void Stop(){playing=false;timer.Stop();if(play!=null)play.Text="▶ Кинематика";}
  void CapturePose(){if(Math.Abs(phase)<1e-9)return;var current=RobotKinematics.Evaluate(Document,phase,true);Mutate(()=>{foreach(var j in Document.Joints)j.Position=current[j.Id].Value;});phase=0;}
  void Undo(){EndPoseEdit();if(undo.Count==0)return;redo.Push(Document.Serialize());Document=RobotDocument.Parse(undo.Pop());Rebuild();}void Redo(){EndPoseEdit();if(redo.Count==0)return;undo.Push(Document.Serialize());Document=RobotDocument.Parse(redo.Pop());Rebuild();}
  bool Confirm(){if(Document.Serialize()==saved)return true;var answer=MessageBox.Show(this,"Сохранить проект робота?","Проект",MessageBoxButtons.YesNoCancel);return answer==DialogResult.No||(answer==DialogResult.Yes&&Save(false));}
  void Replace(RobotDocument d,string file){if(!Confirm())return;Document=d;path=file;selectedJoint=null;selectedPart=null;undo.Clear();redo.Clear();saved=d.Serialize();fitNext=true;Rebuild();}
  void Open(){if(!Confirm())return;using(var d=new OpenFileDialog{Filter="Проект робота|*.robot.json"})if(d.ShowDialog(this)==DialogResult.OK)try{var doc=RobotDocument.Parse(File.ReadAllText(d.FileName));Document=doc;path=d.FileName;selectedJoint=null;selectedPart=null;undo.Clear();redo.Clear();saved=doc.Serialize();fitNext=true;Rebuild();}catch(Exception ex){MessageBox.Show(this,ex.Message);}}
  bool Save(bool choose){try{CapturePose();string file=path;if(choose||file==null)using(var d=new SaveFileDialog{Filter="Проект робота|*.robot.json",FileName="Мой_робот.robot.json"}){if(d.ShowDialog(this)!=DialogResult.OK)return false;file=d.FileName;}Document.Save(file);path=file;saved=Document.Serialize();last=saved;Text="GearLab 5.6 · "+Path.GetFileName(file);return true;}catch(Exception ex){MessageBox.Show(this,ex.Message);return false;}}
  void RestoreRecovery(){try{var d=RobotDocument.Parse(AppSettings.ReadRecovery("robot"));Replace(d,null);}catch(Exception ex){MessageBox.Show(this,ex.Message);}}
  void ExportStep(bool printable,bool selected){try{CapturePose();if(!Build.Model.Valid)throw new Exception(string.Join("; ",Build.Model.Errors));string id=selected?selectedPart:null;if(selected&&(Entry==null||Entry.Guide))throw new Exception("Выберите деталь корпуса / узла.");var model=Build.ForExport(printable,id);using(var d=new SaveFileDialog{Filter="STEP — CAD-тела|*.step",FileName=selected?"Деталь_робота.step":printable?"Корпуса_робота.step":"Робот.step"})if(d.ShowDialog(this)==DialogResult.OK)StepExport.Write(model,d.FileName);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Экспорт");}}
  void ExportStls(){try{if(!Build.Model.Valid)throw new Exception("Исправьте CAD-модель.");using(var d=new SaveFileDialog{Filter="Отдельные STL в ZIP|*.zip",FileName="Детали_робота.zip"})if(d.ShowDialog(this)==DialogResult.OK){using(var stream=File.Create(d.FileName))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){var list=new StringBuilder("Файл;Деталь;Масса кг\r\n");int n=0;foreach(var e in Build.Entries.Values.Where(e=>e.Printable&&!e.Guide)){string name=(++n).ToString("000")+"_"+e.Id+".stl";using(var output=zip.CreateEntry(name,CompressionLevel.Optimal).Open())PrintExport.Stl(e.Part,output);list.AppendLine(name+";\""+e.Part.Label.Replace("\"","\"\"")+"\";"+Engine.F(Build.Mass(e)));}using(var w=new StreamWriter(zip.CreateEntry("Состав.csv").Open(),new UTF8Encoding(true)))w.Write(list);}}}catch(Exception ex){MessageBox.Show(this,ex.Message,"Экспорт STL");}}
  void ExportLoads(){try{using(var d=new SaveFileDialog{Filter="CSV|*.csv",FileName="Нагрузки_робота.csv"})if(d.ShowDialog(this)==DialogResult.OK){var s=new StringBuilder("Шарнир;Единицы;Нужно с запасом;Доступно;Мотор нужно Нм;Об/мин;Состояние\r\n");foreach(var x in Analysis.Joints)s.AppendLine("\""+Document.Find(x.Id).Name.Replace("\"","\"\"")+"\";"+x.Unit+";"+Engine.F(x.Required)+";"+Engine.F(x.Available)+";"+Engine.F(x.MotorRequired)+";"+Engine.F(x.MotorRpm)+";"+x.Message);ReleaseSupport.WriteText(d.FileName,s.ToString(),new UTF8Encoding(true));}}catch(Exception ex){MessageBox.Show(this,ex.Message);}}
  void Variants(){using(var folder=new FolderBrowserDialog{Description="Папка для вариантов корпуса"}){if(folder.ShowDialog(this)!=DialogResult.OK)return;string output=Path.Combine(folder.SelectedPath,"Robot_variants_"+DateTime.Now.ToString("yyyyMMdd_HHmmss"));Directory.CreateDirectory(output);try{var report=new StringBuilder("Вариант;Масса с нагрузкой кг;Макс. отношение нужно/доступно;Файл\r\n");foreach(RobotBodyStyle style in Enum.GetValues(typeof(RobotBodyStyle))){var doc=Document.Clone();doc.BodyEdits.Clear();foreach(var j in doc.Joints)j.BodyStyle=style;var build=RobotCad.Build(doc);if(!build.Model.Valid)throw new Exception(string.Join("; ",build.Model.Errors));var analysis=RobotSolver.Solve(build);string name=style.ToString();StepExport.Write(build.ForExport(true,null),Path.Combine(output,name+".step"));doc.Save(Path.Combine(output,name+".robot.json"));double ratio=analysis.Joints.Where(x=>x.Available>0).Select(x=>x.Required/x.Available).DefaultIfEmpty(0).Max();report.AppendLine(name+";"+Engine.F(analysis.TotalMass)+";"+Engine.F(ratio)+";"+name+".step");}File.WriteAllText(Path.Combine(output,"Сравнение.csv"),report.ToString(),new UTF8Encoding(true));MessageBox.Show(this,"Четыре шаблона корпуса и сравнение сохранены:\n"+output+"\nВарианты построены из параметров звеньев без полигональных/ручных переопределений. Меньшая масса не подтверждает прочность.");}catch(Exception ex){MessageBox.Show(this,ex.Message,"Варианты");}}}
  void Help(){MessageBox.Show(this,"СКЕЛЕТ: добавьте звенья, выберите родителей и типы шарниров. Конец кости и положение мотора можно перетаскивать; размерная привязка задаётся в настройках.\nКОРПУС / CAD: выберите деталь в сцене. Справа доступны локальные размеры; сверху — отверстия, карманы, осевые сечения и эскиз. Настройте монтажный фланец, бурт, четыре винта, подшипник и вывод проводов в параметрах звена.\nПЕРЕДАЧА: «Редуктор» открывает калькулятор; «Свой механизм» — свободную сборку. Примените рассчитанный узел к выбранному шарниру. Габарит без внутренней передачи помечается в проверках.\nПОЛИГОНЫ: создайте сеточную копию детали, правьте вершины, подразделяйте и выдавливайте грани. Такая деталь экспортируется STL/OBJ; для STEP восстановите параметрическое тело.\nНАГРУЗКИ: собственный вес и полезная нагрузка, запас 1,5 по умолчанию. Момент мотора берётся из характеристики на рабочих оборотах, не из одного размера NEMA.\nАНИМАЦИЯ: показывает кинематику. «Принять позу» фиксирует видимые углы в проекте. «Проверить диапазон» оценивает 48 поз, а не все возможные движения.\nПроект .robot.json сохраняет корпуса и изменения. Ctrl+S, Ctrl+Z/Y.\n\nЭто конструктор компоновки и статической оценки. Крепления, столкновения, изготовление и прочность требуют окончательной CAD/инженерной проверки.","Робототехника",MessageBoxButtons.OK,MessageBoxIcon.Information);}
  internal void ApproveTestClose(){allowClose=true;}
  protected override void Dispose(bool disposing){if(disposing&&!disposed){disposed=true;motionKernel.Dispose();bodyDelay.Dispose();bodyKernel.Dispose();robotWeb.Dispose();timer.Dispose();recovery.Dispose();Scene.Dispose();host.Child=null;}base.Dispose(disposing);}
 }
